{
  "rows": [
    {
      "choices": [
        {
          "id": "63679426-3aed-4c2b-9606-5a302d5b8efd",
          "is_correct": false,
          "letter": "A",
          "tag": "Helps Explain",
          "text": "The discharged wastewater made the river more attractive to fish that are the natural predators of bass."
        },
        {
          "id": "d90ea180-b650-4c8c-a0d2-8e4f12f339a5",
          "is_correct": false,
          "letter": "B",
          "tag": "Helps Explain",
          "text": "The discharged water was warmer than the normal river temperature, leading the bass to seek cooler water elsewhere."
        },
        {
          "id": "bf2d72f5-17fb-4b6b-be72-57448118689d",
          "is_correct": true,
          "letter": "C",
          "tag": "Correct",
          "text": "Because of the new plant, access to the part of the river downstream from the plant was improved, leading to an increase in the number of anglers fishing for bass."
        },
        {
          "id": "df299e4e-daa4-41f4-ba85-c0910d2cf51f",
          "is_correct": false,
          "letter": "D",
          "tag": "Helps Explain",
          "text": "Because of the new plant, the level of noise downstream increased, making that section of the river a less popular place for anglers to fish."
        },
        {
          "id": "62dca344-d06f-477a-9e54-855d88959c1f",
          "is_correct": false,
          "letter": "E",
          "tag": "Helps Explain",
          "text": "The discharged wastewater created turbulence that disrupted the vegetation of the river downstream, destroying some of the bass's natural habitat."
        }
      ],
      "correct_choice": "C",
      "id": "2d2443be-da5d-44c1-92b6-eacf65d0b40f",
      "prompt": "Each of the following, if true, could explain the decrease described above EXCEPT:",
      "qid": "PT108-S3-Q6",
      "stimulus": "Shortly after the power plant opened and began discharging its wastewater into the river, there was a decrease in the overall number of bass caught by anglers downstream from the plant."
    },
    {
      "choices": [
        {
          "id": "95991692-99aa-4414-911c-365919a8f336",
          "is_correct": true,
          "letter": "A",
          "tag": "Correct",
          "text": "asserting that the objection is based on a belief about the reliability of clairvoyance rather than on the nature of knowledge or its definition"
        },
        {
          "id": "34bd8d0a-0ec2-4a39-8f08-849f4533b1eb",
          "is_correct": false,
          "letter": "B",
          "tag": "Contradicted",
          "text": "asserting that the case of clairvoyance is one of knowledge even though we do not really believe in clairvoyance as a reliable process"
        },
        {
          "id": "15096c93-3d44-46b1-9d11-fc3014f6f397",
          "is_correct": false,
          "letter": "C",
          "tag": "Contradicted",
          "text": "arguing against the assumption that clairvoyance is unreliable"
        },
        {
          "id": "fa496967-d965-4f10-bcc5-eb28e31f7952",
          "is_correct": false,
          "letter": "D",
          "tag": "Out of Scope: personal choice",
          "text": "explaining that the definition of knowledge is a matter of personal choice"
        },
        {
          "id": "3976281f-826d-4f05-afca-d869efae008c",
          "is_correct": false,
          "letter": "E",
          "tag": "\"Not a Case of \\\"Reliable Process\\\"\" [level=5]",
          "text": "demonstrating that the case of clairvoyance is not a case of knowledge and does not fit the definition of knowledge"
        }
      ],
      "correct_choice": "A",
      "id": "5700edca-2d54-44d4-a3e3-cc2442064523",
      "prompt": "Which one of the following most accurately describes the essayist's method of defending the definition against the objection?",
      "qid": "PT112-S3-Q8",
      "stimulus": "Essayist: Knowledge has been defined as a true belief formed by a reliable process. This definition has been criticized on the grounds that if someone had a reliable power of clairvoyance, we would not accept that person’s claim to know certain things on the basis of this power. I agree that we would reject such claims, but we would do so because we really do not believe in clairvoyance as a reliable process. Were we to believe in clairvoyance, we would accept knowledge claims made on the basis of it."
    },
    {
      "choices": [
        {
          "id": "5735170d-ac5d-4acd-a95d-a237d7029e6c",
          "is_correct": true,
          "letter": "A",
          "tag": "Correct",
          "text": "The subjects who were given vitamin C had a history of suffering from more severe acne than did the subjects receiving a placebo."
        },
        {
          "id": "a934a82e-3a57-477e-bfa0-61472c3e4ad4",
          "is_correct": false,
          "letter": "B",
          "tag": "No Impact",
          "text": "None of the subjects who were given vitamin C took additional doses of vitamin C on their own."
        },
        {
          "id": "f75017f5-0e6e-452f-a605-68b72fce33e9",
          "is_correct": false,
          "letter": "C",
          "tag": "No Impact",
          "text": "During the study, the severity of the subjects' acne was lower than the national average."
        },
        {
          "id": "75ee6f0d-1181-4f16-90d8-cb8c768d6e42",
          "is_correct": false,
          "letter": "D",
          "tag": "Strengthens",
          "text": "Some of the subjects who were given placebos consumed foods during the study that are naturally rich in vitamin C."
        },
        {
          "id": "08a1ad04-1275-46de-bb20-6468db240393",
          "is_correct": false,
          "letter": "E",
          "tag": "No Impact",
          "text": "Some of the subjects who knew their pills were placebos did not actually take the pills they were given."
        }
      ],
      "correct_choice": "A",
      "id": "b5d50460-5685-4225-9494-d18a8649be03",
      "prompt": "Which one of the following, if true, most seriously weakens the argument?",
      "qid": "PT157-S3-Q25",
      "stimulus": "To test the claim that vitamin C is effective in treating acne, scientists administered it to one group of subjects and a placebo to a control group. The group receiving vitamin C had less severe acne during the study than did the control group. It was subsequently discovered, however, that half of the subjects in each group knew which kind of pill they were given. Among those who could not tell, no difference in the severity of acne was found between the two groups. Therefore, we can tentatively conclude that vitamin C has no real benefit in reducing the severity of acne."
    }
  ]
}
